section.code:
{
    type        : "adapter",
    adapterId   : "lmdb",
    adapterType : "lmdb",
    env         : {
        path       : "/var/lib/afw/lmdb",
        mode       : 384,          // 0600 in decimal
        maxreaders : 126,
        maxdbs     : 128,
        mapsize    : 1073741824    // 1 GiB
    },
    limits      : {
        size : { soft : 500,  hard : 1000 },
        time : { soft : 3600, hard : 14400 }
    }
}
